const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.book}</svg>`;
const primary = (text, route) => `<a class="primary" href="#${route}">${text}${icon('arrow')}</a>`;
const back = (text, route) => `<a class="page-back" href="#${route}">${icon('back')}${text}</a>`;
const note = text => `<div class="memory-note">${icon('spark')}<span>${text}</span></div>`;
const steps = index => `<div class="progress-strip">${['認識字形','看筆順','自己寫'].map((s,i)=>`${i ? '<i></i>' : ''}<span class="${i === index ? 'active' : ''}">${String(i+1).padStart(2,'0')} ${s}</span>`).join('')}</div>`;
const paths = [
  'M31.01,33c0.88,0.88,2.75,1.82,5.25,1.75c8.62-0.25,20-2.12,29.5-4.25c1.51-0.34,4.62-0.88,6.62-0.5',
  'M49.76,17.62c0.88,1,1.82,3.26,1.38,5.25c-3.75,16.75-6.25,38.13-5.13,53.63c0.41,5.7,1.88,10.88,3.38,13.62',
  'M65.63,44.12c0.75,1.12,1.16,4.39,0.5,6.12c-4.62,12.26-11.24,23.76-25.37,35.76c-6.86,5.83-15.88,3.75-16.25-8.38c-0.34-10.87,13.38-23.12,32.38-26.74c12.42-2.37,27,1.38,30.5,12.75c4.05,13.18-3.76,26.37-20.88,30.49'
];
const strokeSvg = (numbers = true) => `<svg class="stroke-svg" viewBox="0 0 109 109" role="img" aria-label="あ的三筆筆順示範">${paths.map((d,i)=>`<path data-stroke="${i}" d="${d}"/>`).join('')}${numbers ? '<text x="23" y="35">1</text><text x="42" y="19">2</text><text x="58" y="42">3</text>' : ''}</svg>`;
const sourceNote = '<p class="source-note">筆順：<a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener">KanjiVG</a> · CC BY-SA 3.0 · 示範教材</p>';
const coffeeArt = () => `<svg viewBox="0 0 160 130" role="img" aria-label="一杯咖啡與植物的情境插圖"><ellipse cx="87" cy="106" rx="55" ry="9" fill="#c9d2bc"/><path d="M48 60h69v21c0 19-15 27-34 27S48 98 48 81z" fill="#fffaf0"/><ellipse cx="83" cy="60" rx="35" ry="10" fill="#e1d7bd"/><ellipse cx="83" cy="60" rx="27" ry="6" fill="#775c43"/><path d="M117 65h10c22 0 17 25-9 25" fill="none" stroke="#fffaf0" stroke-width="10"/><path d="M71 43c-14-11 10-14 0-25m23 24c-10-9 8-15 0-24" fill="none" stroke="#879879" stroke-width="2" stroke-linecap="round"/><path d="M24 108V62" stroke="#6f845d" stroke-width="2"/><path d="M24 89C8 85 5 69 12 70c10 1 14 9 12 19m0-12c17-4 25-22 14-19-9 2-15 9-14 19" fill="#93a480"/><path d="M12 100h25l-5 20H17z" fill="#b87960"/></svg>`;
const state = {kana:'あ',script:'hira',filter:'全部',lessonTab:'對話',guide:true,strokes:[],animation:0};
history.scrollRestoration = 'manual';
const main = document.querySelector('#main');
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function home(){return `
  <p class="greeting">你好，今天也一起學一點。</p><h1 class="home-heading">日語，一小步<br>就離生活<em>更近一點。</em></h1>
  <section class="hero"><span class="eyebrow">TODAY'S SMALL STEP</span><h2>先認識，五個新朋友。</h2><p>あ・い・う・え・お<br>看一看、聽一聽，再親手寫一次。</p><span class="kana-decoration" lang="ja">あ</span>${primary('開始今天的 5 個字','kana')}</section>
  <div class="section-title"><h2>先把昨天的想起來</h2><span>約 2 分鐘 · 示範</span></div>
  <button class="review-card" data-action="review"><span class="review-glyphs" lang="ja">シ ツ</span><span><strong>容易混淆，再看一次</strong><small>比較筆畫方向，再收起提示回想</small></span>${icon('chevron')}</button>
  <div class="section-title"><h2>今天，照這樣學就好</h2><span>約 10 分鐘</span></div>
  <ol class="today-plan"><li><span class="step-dot">1</span>認識 5 個假名<span>3 分鐘</span></li><li><span class="step-dot">2</span>看筆順，親手寫<span>4 分鐘</span></li><li><span class="step-dot">3</span>收起提示，想一次<span>3 分鐘</span></li></ol>
  <div class="section-title"><h2>學一句，今天就能用</h2><span>生活日語</span></div><a href="#lesson" class="home-life"><span class="cup-tile">${coffeeArt()}</span><div><h3>用日語，點一杯咖啡</h3><p>從「コーヒー」到一句完整點餐。</p></div>${icon('chevron')}</a>
  <p class="review-explainer">不用一次記完。今天學一點，明天再想一次。</p>`;}
const hiraRows=['あいうえお','かきくけこ','さしすせそ','たちつてと','なにぬねの','はひふへほ','まみむめも','や ゆ よ','らりるれろ','わ   を','ん    '];
const kataRows=['アイウエオ','カキクケコ','サシスセソ','タチツテト','ナニヌネノ','ハヒフヘホ','マミムメモ','ヤ ユ ヨ','ラリルレロ','ワ   ヲ','ン    '];
const kanaWords={あ:['a','あめ','雨','自然張口，短短一拍。'],い:['i','いぬ','狗','嘴角輕輕向兩側，短短一拍。'],う:['u','うみ','海','嘴唇放鬆，不用用力圓唇。'],え:['e','えき','車站','自然張口，不要拖成兩個音。'],お:['o','おにぎり','飯糰','嘴唇輕圓，短短一拍。']};
function kana(){const kata=state.script==='kata';const rows=kata?kataRows:hiraRows;const first=[...rows[0]];const selected=state.kana;const hira=kata?hiraRows.join('').charAt(kataRows.join('').indexOf(selected)):selected;const data=kanaWords[hira];return `
  <div class="page-heading"><span class="eyebrow">THE FIRST STEP</span><h1>五十音，慢慢記。</h1><p>每次一行，讓字形與聲音連在一起。</p></div>
  <nav class="course-switch" aria-label="課程分類"><a class="active" href="#kana">五十音</a><a href="#life">生活課程</a></nav>
  <div class="segmented" aria-label="假名種類"><button data-script="hira" class="${kata?'':'active'}" aria-pressed="${!kata}">平假名</button><button data-script="kata" class="${kata?'active':''}" aria-pressed="${kata}">片假名</button></div>
  <div class="row-title"><strong>${kata?'ア':'あ'}行 · 先學這 5 個</strong><span>第 1 課 / 示範</span></div>
  <div class="kana-row">${first.map((k,i)=>`<button class="kana-tile ${selected===k?'active':''}" data-kana="${k}" aria-pressed="${selected===k}" aria-label="認識${k}"><span class="jp" lang="ja">${k}</span><small>${['a','i','u','e','o'][i]}</small></button>`).join('')}</div>
  <section class="kana-detail"><div class="kana-detail-header"><span class="large-kana jp" lang="ja">${selected}</span><div><h2>${data?`${data[0]} · 短短一拍`:'先看看字形'}</h2><p>${data?data[3]:'這次以「あ」示範學習流程。'}</p><button class="sound-button" data-action="audio">${icon('sound')}聽發音 · 示意</button></div></div>
  ${note(selected==='あ'?'字形小提示：一橫、一豎，最後繞一圈。<br>接著看筆順，把字寫進記憶裡。':'先看字、再連結聲音。<br>收起提示時，試著自己想起來。')}
  ${data?`<div class="word-example"><span class="jp" lang="ja">${data[1]}</span><span>${data[2]}<span class="muted"> · 記在一個詞裡</span></span></div>`:''}
  ${primary(selected==='あ'?'看看 あ 的筆順':'體驗 あ 的筆順示例','stroke')}</section>
  <details><summary>展開完整${kata?'片':'平'}假名表${icon('chevron')}</summary><div class="full-kana">${rows.flatMap(row=>[...row]).map(k=>k===' '?'<span class="empty" aria-hidden="true"></span>':`<button data-kana="${k}" class="${selected===k?'active':''}" aria-label="認識${k}" lang="ja">${k}</button>`).join('')}</div></details>
  <p class="review-explainer">這次先練 5 個字。完整字卡與音檔會在正式開發時補齊。</p>`;}
function stroke(){return `${back('回到五十音','kana')}${steps(1)}<div class="character-title"><div><h1><span lang="ja">あ</span>這樣寫，就記住了。</h1><p>先看一次，再跟著寫一次。</p></div><span class="tag">3 筆</span></div>
  <div class="stroke-board">${strokeSvg()}</div><div class="stroke-step-controls" aria-label="分步筆順"><button data-step="0">① 先橫過來</button><button data-step="1">② 再往下</button><button data-step="2">③ 繞一圈</button></div><p class="stroke-hint" id="stroke-hint">一橫、一豎，最後繞一圈。</p>
  <button class="secondary" data-action="animate">${icon('play')}播放完整筆順</button><div style="height:14px"></div>${note('不要急著寫得漂亮。<br>先記住順序，字形會慢慢穩定。')}<div class="lesson-footer">${primary('換我寫寫看','writing')}</div>${sourceNote}`;}
function writing(){return `${back('再看一次筆順','stroke')}${steps(2)}<div class="page-heading"><h1>親手寫，記得更牢。</h1><p>先沿著淡字描寫，再收起提示試一次。</p></div>
  <div class="segmented"><button class="${state.guide?'active':''}" data-mode="trace" aria-pressed="${state.guide}">① 跟著描寫</button><button class="${state.guide?'':'active'}" data-mode="recall" aria-pressed="${!state.guide}">② 收起提示，默寫</button></div>
  <div class="writing-board ${state.guide?'':'no-guide'}" id="writing-board"><span class="board-label" id="board-label">${state.guide?'描寫 あ · 字跡不保存':'請憑記憶寫出 あ · 字跡不保存'}</span>${strokeSvg(false)}<canvas id="writing-canvas" aria-label="あ的手寫體驗區，使用手指、滑鼠或觸控筆。亦可在紙上書寫後自評。"></canvas></div>
  <div class="tools-row"><button data-action="undo">${icon('undo')}退一筆</button><button data-action="clear">${icon('trash')}重新寫</button><button data-action="compare">${icon('eye')}對照示範</button></div>
  ${note('寫完先不看答案，想一想：<br>我記住字形了嗎？筆順還需要提示嗎？')}
  <section class="self-check"><h2>自己檢查一下</h2><p>這次先自評，不用追求完美字跡。</p><label><input type="checkbox">我有照 3 筆的順序寫</label><label><input type="checkbox">我能收起提示，自己寫一次</label></section>
  <div class="lesson-footer"><button class="primary" data-action="finish-writing">這次練習完成${icon('check')}</button></div>${sourceNote}<p class="review-explainer">也可以在紙上寫，再對照畫面。此樣稿不辨識、不評分，也不保存字跡。</p>`;}
const topics=[['招呼與自介','先學會介紹自己','入門','user'],['購物與付款','問價格，說出想買的東西','N5','bag'],['交通與問路','找到月台，搭對方向','N5','train'],['時間與行程','約一個時間，安排一天','入門','calendar']];
function life(){const empty=state.filter==='N4';const list=topics.filter(t=>state.filter==='全部'||t[2]===state.filter);return `<div class="page-heading"><span class="eyebrow">JAPANESE FOR EVERYDAY LIFE</span><h1>學一點，用在生活裡。</h1><p>從熟悉的情境開始，記住真的用得到的話。</p></div><nav class="course-switch" aria-label="課程分類"><a href="#kana">五十音</a><a class="active" href="#life">生活課程</a></nav><div class="filters" aria-label="課程程度">${['全部','入門','N5','N4'].map(f=>`<button class="${state.filter===f?'active':''}" data-filter="${f}" aria-pressed="${state.filter===f}">${f}</button>`).join('')}</div>
  ${!empty&&state.filter!=='入門'?`<article class="featured-course"><div class="course-art"><div class="jp" lang="ja">ひと休み。<small>LET'S ORDER A COFFEE</small></div>${coffeeArt()}</div><div class="featured-body"><span class="tag">N5 · 飲食與餐廳</span><h2>用日語，點一杯咖啡。</h2><p>今天的目標：禮貌地點一份飲料。</p><div class="course-meta"><span>${icon('clock')}約 8 分鐘</span><span>${icon('book')}3 個單字 · 1 個句型</span></div>${primary('開始這個生活任務','lesson')}</div></article>`:''}
  <div class="section-title"><h2>從你需要的開始</h2><span>課程示範</span></div><div class="life-list">${list.map(t=>`<button class="life-card" data-topic="${t[0]}"><span class="topic-icon">${icon(t[3])}</span><span><h3>${t[0]}</h3><p>${t[1]}</p><span class="topic-status">${t[2]} · 後續教材</span></span>${icon('chevron')}</button>`).join('')}${empty?'<div class="filter-empty">N4 會延伸到說明需求、經驗與計畫。<br>這次可先切回「全部」，體驗點餐單課。</div>':''}</div><p class="review-explainer">同一個主題，之後會從 N5 逐步延伸到 N3。</p>`;}
function lesson(){const tab=state.lessonTab;let content='';if(tab==='對話')content=`<section class="dialogue"><p class="speaker">${icon('user')}你 · 在咖啡店</p><p class="jp" lang="ja"><ruby>コーヒー<rt>kōhī</rt></ruby>を<br><ruby>一つ<rt>ひとつ</rt></ruby>お<ruby>願<rt>ねが</rt></ruby>いします。</p><p class="translation">請給我一杯咖啡。</p><button class="sound-button" data-action="audio">${icon('sound')}聽一句 · 示意</button></section><div class="section-title"><h2>先記住這個小句型</h2><span>一次一個</span></div><div class="phrase-pattern jp"><span class="highlight" lang="ja">想點的東西</span><span lang="ja">を 一つ お願いします。</span><p>換掉品項，就能用同一句話點不同的東西。</p></div><div class="lesson-footer"><button class="primary" data-tab="想一想">收起答案，想一想${icon('arrow')}</button></div>`;
  if(tab==='想一想')content=`<h2>想點一杯咖啡，<br>你會選哪一句？</h2><p class="review-explainer">先在心裡說一次，再選答案。</p><div class="choice-stack"><button class="choice" data-choice="correct"><span>A</span>コーヒーを一つお願いします。</button><button class="choice" data-choice="incorrect"><span>B</span>コーヒーはどこですか。</button></div><div id="choice-feedback" aria-live="polite"></div><div class="lesson-footer"><button class="secondary" data-tab="自己寫">接著，自己寫一句${icon('pen')}</button></div>`;
  if(tab==='自己寫')content=`<h2>換成你想點的飲料。</h2><p class="review-explainer">例如「お茶」（茶）或「コーヒー」（咖啡）。</p><label class="lesson-input-label" for="drink-input">你想點的品項</label><input id="drink-input" class="lesson-input" placeholder="例如：お茶" autocomplete="off" maxlength="30"><div class="phrase-pattern jp"><span class="highlight" id="drink-output" lang="ja">＿＿＿</span><span lang="ja">を 一つ お願いします。</span><p>先用模板串起來，再試著在紙上寫整句。</p></div><div style="height:16px"></div>${note('連到自己的生活，會更有意義。<br>想一想，下次進咖啡店你會怎麼說？')}<div class="lesson-footer"><button class="primary" data-action="finish-lesson">完成這次小任務${icon('check')}</button></div><p class="review-explainer">輸入只用於畫面體驗，不保存或自動批改。</p>`;
  return `${back('生活課程','life')}<div class="page-top"><span class="tag">N5 · 飲食與餐廳</span><p>第 1 個任務 / 示範</p></div><div class="page-heading"><h1>點一杯咖啡。</h1></div><div class="goal-banner"><small>今天學完，我可以</small>用一句話，禮貌地點一份飲料。</div><div class="lesson-tabs" aria-label="單課步驟">${['對話','想一想','自己寫'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}" aria-pressed="${t===tab}">${t}</button>`).join('')}</div>${content}`;}
function placeholder(route){const isExam=route==='exam';return `<div class="page-heading"><span class="eyebrow">NEXT CHAPTER</span><h1>${isExam?'一步一步，走向 N3。':'把學過的，慢慢累積。'}</h1></div><section class="route-placeholder"><span class="tag neutral">後續版本的畫面入口</span><h2 style="margin-top:18px">${isExam?'N5 → N4 → N3':'學習紀錄與作品集'}</h2><p>${isExam?'未來會依序加入分科練習、計時模擬與弱點分析。這次先把五十音與生活課程的學習體驗確認好。':'未來會在這裡看到能力別進度、手寫作品與複習紀錄。樣稿沒有建立帳號或保存資料。'}</p>${primary('回到今日學習','home')}</section>`;}
function review(){return `${back('回到今日','home')}<div class="page-heading"><span class="eyebrow">A LITTLE RECALL</span><h1>シ、ツ，差在哪裡？</h1><p>先找一個差異，再把提示收起來。</p></div><div class="comparison-grid"><div class="comparison-item"><span class="jp" lang="ja">シ</span><strong>shi</strong><p>兩點偏上下<br>長筆由左下往右上 ↗</p></div><div class="comparison-item"><span class="jp" lang="ja">ツ</span><strong>tsu</strong><p>兩點偏左右<br>長筆由右上往左下 ↙</p></div></div><div class="button-row"><button class="secondary" data-action="hide-comparison">${icon('eye')}收起提示，想一次</button></div><div class="section-title"><h2>哪一個讀作 shi？</h2><span>回想示範</span></div><div class="recall-choices"><button data-review-choice="correct" class="choice" lang="ja">シ</button><button data-review-choice="incorrect" class="choice" lang="ja">ツ</button></div><div id="review-feedback" aria-live="polite"></div><div class="lesson-footer">${primary('繼續今天的 5 個字','kana')}</div><p class="review-explainer">提示只幫你找差異；正式教材仍會加入完整筆順與聽辨。</p>`;}
function render(focus=true){const route=location.hash.slice(1)||'home';state.animation++;document.getAnimations().forEach(a=>a.cancel());const views={home,kana,stroke,writing,life,lesson,review};main.innerHTML=views[route]?views[route]():placeholder(route);main.dataset.screen=route;document.title=`${{home:'今日',kana:'五十音',stroke:'筆順',writing:'手寫',life:'生活課程',lesson:'點餐單課',exam:'檢定',profile:'我的',review:'相似字複習'}[route]||'樣稿'}｜日和手機樣稿`;
  const items=[['home','home','今日'],['kana','book','課程'],['writing','pen','練習'],['exam','exam','檢定'],['profile','user','我的']];document.querySelector('#bottom-nav').innerHTML=items.map(([r,i,label])=>`<a href="#${r}" class="${route===r||(r==='kana'&&['life','lesson','stroke'].includes(route))?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');document.querySelectorAll('[data-review]').forEach(a=>{a.classList.toggle('active',a.dataset.review===route);if(a.dataset.review===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='writing')setupCanvas();if(focus){window.scrollTo(0,0);main.focus({preventScroll:true});}}
let drawCanvas, drawContext, currentStroke=null;
function redraw(){if(!drawCanvas)return;const size=drawCanvas.getBoundingClientRect().width;const ratio=window.devicePixelRatio||1;drawCanvas.width=Math.round(size*ratio);drawCanvas.height=Math.round(size*ratio);drawContext=drawCanvas.getContext('2d');drawContext.scale(ratio,ratio);drawContext.strokeStyle='#455f4e';drawContext.fillStyle='#455f4e';drawContext.lineWidth=3.5;drawContext.lineCap='round';drawContext.lineJoin='round';for(const points of state.strokes){if(points.length===1){drawContext.beginPath();drawContext.arc(points[0].x*size,points[0].y*size,1.75,0,Math.PI*2);drawContext.fill();continue;}drawContext.beginPath();points.forEach((p,i)=>{if(i===0)drawContext.moveTo(p.x*size,p.y*size);else drawContext.lineTo(p.x*size,p.y*size);});drawContext.stroke();}}
function setupCanvas(){drawCanvas=document.querySelector('#writing-canvas');redraw();const point=e=>{const r=drawCanvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};drawCanvas.addEventListener('pointerdown',e=>{if(e.button!==0||currentStroke)return;drawCanvas.setPointerCapture(e.pointerId);currentStroke={id:e.pointerId,points:[point(e)]};state.strokes.push(currentStroke.points);redraw();});drawCanvas.addEventListener('pointermove',e=>{if(!currentStroke||e.pointerId!==currentStroke.id)return;currentStroke.points.push(point(e));redraw();});const stop=e=>{if(currentStroke&&e.pointerId===currentStroke.id)currentStroke=null;};['pointerup','pointercancel','lostpointercapture'].forEach(name=>drawCanvas.addEventListener(name,stop));}
function selectStep(step){const current=++state.animation;const pathElements=[...document.querySelectorAll('.stroke-board path')];document.getAnimations().forEach(a=>a.cancel());pathElements.forEach((p,i)=>{p.style.opacity=i<=step?'1':'.12';p.style.strokeDasharray='';p.style.strokeDashoffset='';});document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===step));document.querySelector('#stroke-hint').textContent=['第 1 筆：從左向右，輕輕橫過來。','第 2 筆：從上往下，稍微彎一下。','第 3 筆：沿著路徑繞出字形。'][step];const p=pathElements[step],length=p.getTotalLength();if(!matchMedia('(prefers-reduced-motion: reduce)').matches){p.style.strokeDasharray=length;p.animate([{strokeDashoffset:length},{strokeDashoffset:0}],{duration:850,fill:'forwards'});}return current;}
async function animateStroke(){const token=++state.animation;document.getAnimations().forEach(a=>a.cancel());const els=[...document.querySelectorAll('.stroke-board path')];els.forEach(p=>{p.style.opacity='.12';p.style.strokeDasharray='';});const labels=['第 1 筆：先橫過來。','第 2 筆：再往下。','第 3 筆：最後繞一圈。'];for(let i=0;i<els.length;i++){if(token!==state.animation)return;const p=els[i];p.style.opacity='1';document.querySelector('#stroke-hint').textContent=labels[i];document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===i));if(matchMedia('(prefers-reduced-motion: reduce)').matches)continue;const len=p.getTotalLength();p.style.strokeDasharray=len;try{await p.animate([{strokeDashoffset:len},{strokeDashoffset:0}],{duration:850,fill:'forwards'}).finished;}catch{return;}}if(token===state.animation)document.querySelector('#stroke-hint').textContent='一橫、一豎，最後繞一圈。換你試試看。';}
document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;const d=el.dataset;if(d.script){state.script=d.script;state.kana=d.script==='hira'?'あ':'ア';render(false);}if(d.kana){state.kana=d.kana;const expanded=!!document.querySelector('details[open]');render(false);if(expanded)document.querySelector('details').open=true;}if(d.filter){state.filter=d.filter;render(false);}if(d.tab){state.lessonTab=d.tab;render(false);}if(d.mode){state.guide=d.mode==='trace';const board=document.querySelector('#writing-board');board.classList.toggle('no-guide',!state.guide);board.classList.remove('compare');document.querySelector('#board-label').textContent=state.guide?'描寫 あ · 字跡不保存':'請憑記憶寫出 あ · 字跡不保存';document.querySelectorAll('[data-mode]').forEach(b=>{const active=(b.dataset.mode==='trace')===state.guide;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}if(d.step!==undefined)selectStep(Number(d.step));if(d.topic)toast(`「${d.topic}」教材尚未製作。這次請體驗咖啡點餐課。`);if(d.choice){document.querySelectorAll('.choice').forEach(b=>b.classList.remove('correct','incorrect'));el.classList.add(d.choice);document.querySelector('#choice-feedback').innerHTML=d.choice==='correct'?'<div class="feedback">選對了！「を一つお願いします」可以用來點一份東西。接著換一個品項試試。</div>':'<div class="feedback error">這句是在問「咖啡在哪裡？」。點餐時試試「を一つお願いします」。</div>';}
  if(d.reviewChoice){document.querySelectorAll('[data-review-choice]').forEach(b=>b.classList.remove('correct','incorrect'));el.classList.add(d.reviewChoice);document.querySelector('#review-feedback').innerHTML=d.reviewChoice==='correct'?'<div class="feedback">想對了！シ讀作 shi。記住它長筆往右上，之後再回想一次。</div>':'<div class="feedback error">這是ツ，讀作 tsu。再想想，長筆往右上的是哪一個？</div>';}
  const actions={audio:()=>toast('播放位置示範：正式日語音檔尚未接入。'),review:()=>{location.hash='review';},'hide-comparison':()=>{const grid=document.querySelector('.comparison-grid');grid.classList.toggle('hide-hints');el.innerHTML=icon('eye')+(grid.classList.contains('hide-hints')?'再看一次提示':'收起提示，想一次');},animate:animateStroke,undo:()=>{state.strokes.pop();redraw();},clear:()=>{state.strokes=[];redraw();},compare:()=>{const board=document.querySelector('#writing-board');board.classList.toggle('compare');board.classList.toggle('no-guide',!board.classList.contains('compare')&&!state.guide);toast('對照示範，自評字形與順序；此樣稿不自動評分。');},'finish-writing':()=>toast('這次體驗完成。正式版本會安排複習；目前不保存進度。'),'finish-lesson':()=>toast('小任務體驗完成！輸入與進度不保存。')};if(actions[d.action])actions[d.action]();});
document.addEventListener('input',event=>{if(event.target.id==='drink-input')document.querySelector('#drink-output').textContent=event.target.value.trim()||'＿＿＿';});
document.querySelector('#preview-info').innerHTML=icon('info');document.querySelector('#preview-info').addEventListener('click',()=>document.querySelector('#info-dialog').showModal());document.querySelector('#close-dialog').addEventListener('click',()=>document.querySelector('#info-dialog').close());window.addEventListener('hashchange',()=>{currentStroke=null;render();});window.addEventListener('resize',()=>{if(location.hash==='#writing')redraw();});render(false);
